function shortestPalindrome(s) {
  const reversed = s.split('').reverse().join('');
  const combined = s + '#' + reversed;
  const lps = new Array(combined.length).fill(0);
  for (let i = 1; i < combined.length; i++) {
    let length = lps[i - 1];
    while (length > 0 && combined[i] !== combined[length]) {
      length = lps[length - 1];
    }
    if (combined[i] === combined[length]) {
      length++;
    }
    lps[i] = length;
  }
  const palindromeLength = lps[combined.length - 1];
  return reversed.slice(0, s.length - palindromeLength) + s;
}

