function shortestPalindrome(s) {
  // Find the longest prefix that reads the same both ways, trying lengths from longest to shortest.
  const isPalindrome = (from, to) => {
    while (from < to) {
      if (s[from] !== s[to]) return false;
      from++;
      to--;
    }
    return true;
  };
  let keep = s.length;
  while (keep > 0 && !isPalindrome(0, keep - 1)) keep--;
  let front = '';
  for (let k = s.length - 1; k >= keep; k--) front += s[k];
  return front + s;
}

