function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const alphabet = size === 'large' ? (rand() < 0.5 ? 'ab' : 'abcdefghijklmnopqrstuvwxyz') : rand() < 0.7 ? 'ab' : 'abc';
  const randomString = length => Array.from({ length }, () => alphabet[pick(alphabet.length)]).join('');
  const total = size === 'large' ? 9000 + pick(1000) : pick(9);
  const mode = pick(3);
  if (mode === 0) return [randomString(total)];
  // Start with a palindrome so the answer keeps a long prefix, then add a random tail.
  const half = randomString(Math.floor(total * (mode === 1 ? 0.45 : 0.3)));
  const middle = rand() < 0.5 ? randomString(1) : '';
  const palindrome = half + middle + half.split('').reverse().join('');
  return [palindrome + randomString(Math.max(0, total - palindrome.length))];
}
